class Solution:
    def rotateNonNegative(self, nums: list[int], k: int) -> list[int]:
        indices = [i for i, x in enumerate(nums) if x >= 0]
        if not indices:
            return nums

        m = len(indices)
        k %= m
        vals = [nums[i] for i in indices]
        rotated = vals[-k:] + vals[:-k]

        res = list(nums)
        for idx, val in zip(indices, rotated):
            res[idx] = val
        return res

#include <vector>
using namespace std;

class Solution {
public:
    vector<int> rotateNonNegative(vector<int>& nums, int k) {
        vector<int> indices;
        for (int i = 0; i < (int)nums.size(); i++) {
            if (nums[i] >= 0) indices.push_back(i);
        }
        if (indices.empty()) return nums;
        int m = indices.size();
        k %= m;
        vector<int> vals;
        for (int i : indices) vals.push_back(nums[i]);
        vector<int> res = nums;
        for (int i = 0; i < m; i++) {
            int src = (i - k + m) % m;
            res[indices[i]] = vals[src];
        }
        return res;
    }
};

import java.util.*;

class Solution {
    public int[] rotateNonNegative(int[] nums, int k) {
        List<Integer> indices = new ArrayList<>();
        for (int i = 0; i < nums.length; i++) {
            if (nums[i] >= 0) indices.add(i);
        }
        if (indices.isEmpty()) return nums;
        int m = indices.size();
        k %= m;
        int[] vals = new int[m];
        for (int i = 0; i < m; i++) vals[i] = nums[indices.get(i)];
        int[] res = nums.clone();
        for (int i = 0; i < m; i++) {
            int src = (i - k + m) % m;
            res[indices.get(i)] = vals[src];
        }
        return res;
    }
}

var rotateNonNegative = function(nums, k) {
    const indices = [];
    for (let i = 0; i < nums.length; i++) {
        if (nums[i] >= 0) indices.push(i);
    }
    if (indices.length === 0) return nums;
    const m = indices.length;
    k %= m;
    const vals = indices.map(i => nums[i]);
    const res = [...nums];
    for (let i = 0; i < m; i++) {
        const src = (i - k + m) % m;
        res[indices[i]] = vals[src];
    }
    return res;
};
